`include "constants.vams"
`include "disciplines.vams"

module vdiode(a, c);
  inout a, c;
  electrical a, c, ai;            // ai: internal node after the series resistance
  parameter real is  = 1e-14 from (0:inf);
  parameter real n   = 1.0   from (0:inf);
  parameter real rs  = 10    from [0:inf);
  parameter real cj0 = 1p    from [0:inf);
  parameter real vj  = 0.7   from (0:inf);
  parameter real m   = 0.5   from (0:1);
  parameter real tt  = 5n    from [0:inf);
  parameter real kf  = 0     from [0:inf);
  parameter real af  = 1     from (0:inf);
  (* desc="diode current", units="A" *) real id;
  (* desc="small-signal conductance", units="S" *) real gd;
  real vd, vt, qj;
  analog begin
    vt = `P_K * $temperature / `P_Q;
    vd = V(ai, c);
    id = is * (limexp(vd / (n * vt)) - 1);
    gd = is / (n * vt) * limexp(vd / (n * vt));
    if (vd < 0.5 * vj)
      qj = cj0 * vj / (1 - m) * (1 - pow(1 - vd / vj, 1 - m));
    else   // linear extension above vj/2 keeps the charge finite
      qj = cj0 * vj / (1 - m) * (1 - pow(0.5, 1 - m))
         + cj0 / pow(0.5, m) * (vd - 0.5 * vj);
    I(ai, c) <+ id + ddt(tt * id + qj);
    if (rs > 0) I(a, ai) <+ V(a, ai) / rs; else V(a, ai) <+ 0;
    I(ai, c) <+ white_noise(2 * `P_Q * abs(id), "shot");
    I(ai, c) <+ flicker_noise(kf * pow(abs(id), af), 1, "flicker");
    if (rs > 0) I(a, ai) <+ white_noise(4 * `P_K * $temperature / rs, "thermal");
  end
endmodule

`include "constants.vams"
`include "disciplines.vams"

module shres(p, n);
  inout p, n;
  electrical p, n;
  thermal dt;                          // internal node: temperature rise in kelvin
  parameter real r0  = 100   from (0:inf);   // resistance at ambient
  parameter real tc1 = 4e-3;                 // 1/K
  parameter real rth = 500   from (0:inf);   // K/W
  parameter real cth = 1e-3  from (0:inf);   // J/K
  (* desc="temperature rise", units="K" *) real trise;
  (* desc="resistance", units="Ohm" *) real r;
  real p_el;
  analog begin
    trise = Temp(dt);
    r = r0 * (1 + tc1 * trise);
    I(p, n) <+ V(p, n) / r;
    p_el = V(p, n) * V(p, n) / r;
    Pwr(dt) <+ -p_el;                  // heat flows into the thermal node
    Pwr(dt) <+ Temp(dt) / rth + ddt(cth * Temp(dt));
  end
endmodule

`include "disciplines.vams"

// an ideal integrator: v(o) = k * integral of v(i) dt
module integ(i, o);
  inout i, o;
  electrical i, o;
  parameter real k = 1k;
  analog V(o) <+ k * idt(V(i), 0);
endmodule
